mapper.update:
UPDATE course
course_code = #{courseCode}, title = #{title}, term_start_date = #{termStartDate}, term_end_date = #{termEndDate}, description = #{description}, location = #{location}, instructor_id = #{instructorId},
WHERE id = #{id}

UPDATE course
course_code = #{course.courseCode}, title = #{course.title}, term_start_date = #{course.termStartDate}, term_end_date = #{course.termEndDate}, description = #{course.description}, description = NULL, location = #{course.location}, location = NULL, instructor_id = #{course.instructorId},
WHERE id = #{course.id}

UPDATE course
SET state = 'Archived',
    archived_at = #{archivedAt},
    archived_by_actor_type = #{archivedByActorType},
    archived_by_actor_id = #{archivedByActorId}
WHERE id = #{id}

where.if:
AND (
    instructor_id = #{instructorUserId}
    OR id IN (
        SELECT course_id FROM enrollment
        WHERE user_id = #{instructorUserId}
          AND course_role = 'Instructor'
          AND active = 1
    )
)

mapper.select:
SELECT
FROM course
ORDER BY updated_at DESC, id DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM course
WHERE tenant_id = #{tenantId}

SELECT COUNT(*)
FROM course
WHERE instructor_id = #{userId}
   OR creator_id = #{userId}
